async function geometry(name){const g=await ev(`({width:innerWidth,scroll:document.documentElement.scrollWidth,dialog:document.querySelector('dialog[open]')?.getBoundingClientRect().toJSON(),badImages:[...document.images].filter(e=>e.getBoundingClientRect().width&&!e.naturalWidth).map(e=>e.src)})`);assert(g.scroll<=g.width+1,name+JSON.stringify(g));assert(!g.badImages.length,name+JSON.stringify(g));if(g.dialog)assert(g.dialog.x>=-1&&g.dialog.right<=g.width+1,name+JSON.stringify(g));const styles=await ev(`(()=>{const selectors=['.juyi-page','.production-page-header','.all-pages-panel','.baseline-page','.panel-return','.composer-input-area','.composer-send','.hall-conversation-history'];return Object.fromEntries(selectors.map(selector=>{const e=document.querySelector(selector);if(!e)return[selector,null];const s=getComputedStyle(e);return[selector,{background:s.backgroundColor,color:s.color,font:s.fontFamily,fontSize:s.fontSize,lineHeight:s.lineHeight,borderRadius:s.borderRadius,padding:s.padding,display:s.display}]}))})()`);layouts.push({name,...g,styles});}
